"""
MXFP4 MoE: Probe v3 - dump ALL positional args to ck_moe_stage1/2.
Now we know: kernelName="" (empty string), str2dtype_dict={'f16','b16'}.
Need exact arg positions and values for direct dispatch.
"""

import os
import sys
import torch
from task import input_t, output_t

os.environ["AITER_USE_NT"] = "1"

from aiter import ActivationType, QuantType
from aiter.fused_moe import fused_moe

_call_count = {"s1": 0, "s2": 0}
_patched = {"done": False}
_orig_fused_moe = fused_moe


def _dump_arg(i, a):
    """Format an arg for printing."""
    if isinstance(a, torch.Tensor):
        return f"Tensor({a.shape}, {a.dtype})"
    return repr(a)


def _patched_fused_moe(*args, **kwargs):
    if not _patched["done"]:
        _patched["done"] = True
        try:
            ops = torch.ops.aiter
            if hasattr(ops, "ck_moe_stage1"):
                orig_s1 = ops.ck_moe_stage1
                def _wrap_s1(*a, **kw):
                    _call_count["s1"] += 1
                    if _call_count["s1"] <= 2:
                        print(f"\n[S1-CALL-{_call_count['s1']}] nargs={len(a)} kwargs={list(kw.keys())}", file=sys.stderr)
                        for i, v in enumerate(a):
                            print(f"  arg[{i}] = {_dump_arg(i, v)}", file=sys.stderr)
                        for k, v in kw.items():
                            print(f"  kw[{k}] = {_dump_arg(k, v)}", file=sys.stderr)
                    return orig_s1(*a, **kw)
                ops.ck_moe_stage1 = _wrap_s1

            if hasattr(ops, "ck_moe_stage2"):
                orig_s2 = ops.ck_moe_stage2
                def _wrap_s2(*a, **kw):
                    _call_count["s2"] += 1
                    if _call_count["s2"] <= 2:
                        print(f"\n[S2-CALL-{_call_count['s2']}] nargs={len(a)} kwargs={list(kw.keys())}", file=sys.stderr)
                        for i, v in enumerate(a):
                            print(f"  arg[{i}] = {_dump_arg(i, v)}", file=sys.stderr)
                        for k, v in kw.items():
                            print(f"  kw[{k}] = {_dump_arg(k, v)}", file=sys.stderr)
                    return orig_s2(*a, **kw)
                ops.ck_moe_stage2 = _wrap_s2
        except Exception as e:
            import traceback
            print(f"[probe] Patch failed: {e}", file=sys.stderr)
            traceback.print_exc(file=sys.stderr)

    return _orig_fused_moe(*args, **kwargs)


def custom_kernel(data: input_t) -> output_t:
    (
        hidden_states, gate_up_weight, down_weight,
        gate_up_weight_scale, down_weight_scale,
        gate_up_weight_shuffled, down_weight_shuffled,
        gate_up_weight_scale_shuffled, down_weight_scale_shuffled,
        topk_weights, topk_ids, config,
    ) = data

    hidden_pad = config["d_hidden_pad"] - config["d_hidden"]
    intermediate_pad = config["d_expert_pad"] - config["d_expert"]

    return _patched_fused_moe(
        hidden_states, gate_up_weight_shuffled, down_weight_shuffled,
        topk_weights, topk_ids, expert_mask=None,
        activation=ActivationType.Silu, quant_type=QuantType.per_1x32,
        doweight_stage1=False,
        w1_scale=gate_up_weight_scale_shuffled,
        w2_scale=down_weight_scale_shuffled,
        a1_scale=None, a2_scale=None,
        hidden_pad=hidden_pad, intermediate_pad=intermediate_pad,
    )

