"""
MXFP4 GEMM: torch.compile fusion of quant + shuffle + ASM GEMM.
Goal: Fuse the ~10µs quantization overhead into the GEMM pipeline.
"""

import torch
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_config_cache: dict = {}
_out_buf: dict = {}
_compiled_fn = None


def _kernel_name(tile_m, tile_n):
    sym = f"f4gemm_bf16_per1x32Fp4_BpreShuffle_{tile_m}x{tile_n}"
    return f"_ZN5aiter{len(sym)}{sym}E"


def _get_config(M, N, K):
    key = (M, N, K)
    if key not in _config_cache:
        kernel_name = None
        split_k = None
        try:
            cfg = get_GEMM_config(M, N, K)
            if isinstance(cfg, dict):
                kn = cfg.get("kernelName")
                if kn is not None:
                    kernel_name = str(kn)
                sk = cfg.get("splitK")
                if sk is not None and int(sk) > 0:
                    split_k = int(sk)
            elif cfg is not None:
                kernel_name = str(cfg)
        except Exception:
            pass

        if kernel_name is None:
            kernel_name = _kernel_name(32, 128)

        _config_cache[key] = (kernel_name, split_k)
    return _config_cache[key]


def _quant_and_gemm(A, B_shuffle, B_scale_sh, out, kernel_name, log2_ks):
    """Core pipeline: quant A → shuffle scales → ASM GEMM."""
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A)
    A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
    A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    return aiter.gemm_a4w4_asm(
        A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
        out, kernel_name, bpreshuffle=True, log2_k_split=log2_ks,
    )


# Try torch.compile with different backends
_compile_attempted = False
_compiled_quant = None


def custom_kernel(data: input_t) -> output_t:
    global _compile_attempted, _compiled_quant

    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    kernel_name, log2_ks = _get_config(M, N, K)

    # Try compiled quantization (fuse quant + shuffle into single kernel)
    if not _compile_attempted:
        _compile_attempted = True
        try:
            @torch.compile(backend="inductor", mode="max-autotune-no-cudagraphs")
            def _compiled_quant_fn(x):
                x_fp4, bs_e8m0 = dynamic_mxfp4_quant(x)
                A_q = x_fp4.view(dtypes.fp4x2)
                A_s = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
                return A_q, A_s
            # Warmup
            _compiled_quant_fn(A.contiguous())
            _compiled_quant = _compiled_quant_fn
        except Exception:
            _compiled_quant = None

    A_cont = A.contiguous()

    if _compiled_quant is not None:
        try:
            A_q_fp4x2, A_scale_sh = _compiled_quant(A_cont)
        except Exception:
            x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A_cont)
            A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
            A_scale_sh = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
    else:
        x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A_cont)
        A_q_fp4x2 = x_fp4.view(dtypes.fp4x2)
