"""
MXFP4 GEMM: Probe CSV configs for blockscale and ASM kernels.
Dumps first 30 rows of a4w4_blockscale_tuned_gemm.csv to stderr.
Also searches for our competition shapes.
Falls back to proven ASM.
"""

import sys
import pathlib
import torch
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

# Dump blockscale tuned CSV
csv_path = pathlib.Path("/home/runner/aiter/aiter/configs/a4w4_blockscale_tuned_gemm.csv")
if csv_path.exists():
    lines = csv_path.read_text().strip().split('\n')
    print(f"[CSV] a4w4_blockscale_tuned_gemm.csv: {len(lines)} lines", file=sys.stderr)
    for line in lines[:3]:
        print(f"[CSV]   {line}", file=sys.stderr)

    # Competition shapes: M=4/N=2880/K=512, M=16/N=2112/K=7168, M=32/N=4096/K=512,
    # M=32/N=2880/K=512, M=64/N=7168/K=2048, M=256/N=3072/K=1536
    comp_shapes = [(4,2880,512), (16,2112,7168), (32,4096,512),
                   (32,2880,512), (64,7168,2048), (256,3072,1536)]
    for m, n, k in comp_shapes:
        matches = [l for l in lines[1:] if f",{m},{n},{k}," in l]
        if matches:
            for match in matches[:3]:
                print(f"[CSV] MATCH ({m},{n},{k}): {match}", file=sys.stderr)
        else:
            print(f"[CSV] NO MATCH ({m},{n},{k})", file=sys.stderr)

# Also dump untuned CSV (shapes that failed tuning)
untuned = pathlib.Path("/home/runner/aiter/aiter/configs/a4w4_blockscale_untuned_gemm.csv")
if untuned.exists():
    lines = untuned.read_text().strip().split('\n')
    print(f"[CSV] a4w4_blockscale_untuned_gemm.csv: {len(lines)} lines", file=sys.stderr)
    for m, n, k in comp_shapes:
        matches = [l for l in lines[1:] if f"{m},{n},{k}" in l]
        if matches:
            print(f"[CSV] UNTUNED ({m},{n},{k}): {matches[0]}", file=sys.stderr)

# Dump what configs get_GEMM_config returns for our shapes
for m, n, k in comp_shapes:
    try:
        cfg = get_GEMM_config(m, n, k)
        print(f"[CFG] ({m},{n},{k}): {cfg}", file=sys.stderr)
    except Exception as e:
        print(f"[CFG] ({m},{n},{k}): ERROR {e}", file=sys.stderr)


# Standard ASM path
_out_buf: dict = {}
_config_cache: dict = {}


def _kernel_name(tile_m, tile_n):
    sym = f"f4gemm_bf16_per1x32Fp4_BpreShuffle_{tile_m}x{tile_n}"
    return f"_ZN5aiter{len(sym)}{sym}E"


def _get_config(M, N, K):
    key = (M, N, K)
    if key not in _config_cache:
        kernel_name = None
        split_k = None
        try:
            cfg = get_GEMM_config(M, N, K)
            if isinstance(cfg, dict):
                kn = cfg.get("kernelName")
                if kn is not None:
                    kernel_name = str(kn)
                sk = cfg.get("splitK")
                if sk is not None and int(sk) > 0:
                    split_k = int(sk)
            elif cfg is not None:
                kernel_name = str(cfg)
        except Exception:
            pass
        if kernel_name is None:
            kernel_name = _kernel_name(32, 128)
        _config_cache[key] = (kernel_name, split_k)
    return _config_cache[key]


def custom_kernel(data: input_t) -> output_t:
    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    kernel_name, log2_ks = _get_config(M, N, K)

    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)

    mn_key = (M, N)
    if mn_key not in _out_buf:
        _out_buf[mn_key] = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    out = _out_buf[mn_key]

    return aiter.gemm_a4w4_asm(
        A_q, B_shuffle, A_scale, B_scale_sh,
        out, kernel_name, bpreshuffle=True, log2_k_split=log2_ks,
    )

