"""
MXFP4 GEMM: Baseline submission using aiter gemm_a4w4_asm.

Current: 14.1 µs geomean (baseline for K-Search optimization)
Target: 9.7 µs (leader: 9.671 µs)

Submit via:
    popcorn-cli submit --mode test --gpu MI355X --leaderboard amd-mxfp4-mm submission.py
"""

import torch
from task import input_t, output_t
from reference import ref_kernel

def custom_kernel(data: input_t) -> output_t:
    """Delegate to reference (aiter gemm_a4w4_asm with tuned configs)."""
    return ref_kernel(data)

if __name__ == "__main__":
    print("Baseline submission ready for Popcorn CLI")
#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>
#include <stdint.h>
#include <math.h>

constexpr int WARP_SIZE = 64;
constexpr int BLOCK_M = 256;
constexpr int BLOCK_N = 256;
constexpr int BLOCK_K = 128;
constexpr int NUM_THREADS = 512;
constexpr float FP4_MAX = 6.0f;
constexpr int E8M0_BIAS = 127;

__device__ __forceinline__ void quantize_bf16_to_fp4(
    hip_bfloat16 val,
    uint8_t& scale_exp,
    uint8_t& fp4_val
) {
    float f = __bfloat162float(val);
    float abs_f = fabsf(f);

    if (abs_f > 0.0f) {
        int exp;
        frexpf(abs_f, &exp);
        uint32_t bits = __float_as_uint(abs_f);
        uint32_t rounded = (bits + 0x200000u) & 0xFF800000u;
        int exp_biased = (rounded >> 23) & 0xFF;
        scale_exp = exp_biased - 2;

        float quant_scale = exp2f(129.0f - (float)scale_exp);

