"""
MXFP4 GEMM: Hybrid Triton + ASM per-shape routing.
- Small M with large K (M<=16, K>=4096): gemm_afp4wfp4 (Triton persistent, NUM_KSPLIT=16)
- All other shapes: gemm_a4w4_asm (ASM, faster for medium/large M)

Hypothesis: Triton persistent kernel's aggressive K-splitting (16-way) may beat
ASM's 2-way split for the bottleneck M=16,K=7168 shape.
"""

import sys
import torch
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_config_cache: dict = {}
_out_buf: dict = {}
_ncalls = 0

# Import Triton persistent kernel
try:
    from aiter.ops.triton.gemm_afp4wfp4 import gemm_afp4wfp4
    _HAS_TRITON = True
except ImportError:
    _HAS_TRITON = False


def _kernel_name(tile_m, tile_n):
    sym = f"f4gemm_bf16_per1x32Fp4_BpreShuffle_{tile_m}x{tile_n}"
    return f"_ZN5aiter{len(sym)}{sym}E"


def _get_asm_config(M, N, K):
    key = (M, N, K)
    if key not in _config_cache:
        kernel_name = None
        split_k = None
        try:
            cfg = get_GEMM_config(M, N, K)
            if isinstance(cfg, dict):
                kn = cfg.get("kernelName")
                if kn is not None:
                    kernel_name = str(kn)
                sk = cfg.get("splitK")
                if sk is not None and int(sk) > 0:
                    split_k = int(sk)
        except Exception:
            pass
        if kernel_name is None:
            if M >= 128:
                kernel_name = _kernel_name(192, 128)
            else:
                kernel_name = _kernel_name(32, 128)
        _config_cache[key] = (kernel_name, split_k)
    return _config_cache[key]


def _use_triton(M, K):
    """Route small-M, large-K shapes to Triton persistent kernel."""
    return _HAS_TRITON and M <= 16 and K >= 4096


def custom_kernel(data: input_t) -> output_t:
    global _ncalls
    _ncalls += 1

    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    # Quantize A
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)

    mn_key = (M, N)
    if mn_key not in _out_buf:
        _out_buf[mn_key] = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    out = _out_buf[mn_key]

    if _use_triton(M, K):
        # Triton persistent kernel with NUM_KSPLIT=16 for small-M
        result = gemm_afp4wfp4(A_q, B_shuffle, A_scale, B_scale_sh)
        if _ncalls <= 6:
            print(f"[HYBRID] TRITON ({M},{N},{K}): shape={result.shape}, dtype={result.dtype}", file=sys.stderr)
        if result.dtype == torch.float32 and result.dim() == 3:
            out.copy_(result.sum(dim=0).to(torch.bfloat16))
        elif result.dtype != torch.bfloat16:
            out.copy_(result.to(torch.bfloat16))
        elif result.data_ptr() != out.data_ptr():
            out.copy_(result)
        return out
    else:
        # ASM path for medium/large M
        kernel_name, log2_ks = _get_asm_config(M, N, K)
        if _ncalls <= 6:
            print(f"[HYBRID] ASM ({M},{N},{K}): tile={kernel_name[-15:]}, ks={log2_ks}", file=sys.stderr)
        return aiter.gemm_a4w4_asm(
            A_q, B_shuffle, A_scale, B_scale_sh,
            out, kernel_name, bpreshuffle=True, log2_k_split=log2_ks,
        )

