"""
MXFP4 GEMM: Probe torch._scaled_mm_v2 and ref_kernel internals.
"""

import sys
import inspect
import torch
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_config_cache: dict = {}
_out_buf: dict = {}
_ncalls = 0


def _kernel_name(tile_m, tile_n):
    sym = f"f4gemm_bf16_per1x32Fp4_BpreShuffle_{tile_m}x{tile_n}"
    return f"_ZN5aiter{len(sym)}{sym}E"


def _get_config(M, N, K):
    key = (M, N, K)
    if key not in _config_cache:
        kernel_name = None
        split_k = None
        try:
            cfg = get_GEMM_config(M, N, K)
            if isinstance(cfg, dict):
                kn = cfg.get("kernelName")
                if kn is not None:
                    kernel_name = str(kn)
                sk = cfg.get("splitK")
                if sk is not None and int(sk) > 0:
                    split_k = int(sk)
        except Exception:
            pass
        if kernel_name is None:
            kernel_name = _kernel_name(32, 128)
        _config_cache[key] = (kernel_name, split_k)
    return _config_cache[key]


def custom_kernel(data: input_t) -> output_t:
    global _ncalls
    _ncalls += 1

    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    if _ncalls == 1:
        # Probe _scaled_mm_v2
        try:
            v2 = torch.ops.aten._scaled_mm_v2
            print(f"[V2] _scaled_mm_v2 exists", file=sys.stderr)
            try:
                sig = inspect.signature(v2)
                print(f"[V2] sig: {sig}", file=sys.stderr)
            except Exception:
                # Try calling with fp4 inputs
                x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
                try:
                    result = v2(x_fp4, B_q.t(), scale_a=bs_e8m0, scale_b=B_scale_sh)
                    print(f"[V2] SUCCESS: {result.shape} {result.dtype}", file=sys.stderr)
                except Exception as e:
                    print(f"[V2] call failed: {type(e).__name__}: {str(e)[:300]}", file=sys.stderr)
        except Exception as e:
            print(f"[V2] not available: {e}", file=sys.stderr)

        # Probe _scaled_grouped_mm
        try:
            sgm = torch.ops.aten._scaled_grouped_mm
            print(f"[SGM] _scaled_grouped_mm exists", file=sys.stderr)
            try:
                sig = inspect.signature(sgm)
                print(f"[SGM] sig: {sig}", file=sys.stderr)
            except Exception as e:
                print(f"[SGM] no sig: {e}", file=sys.stderr)
        except Exception as e:
            print(f"[SGM] not available: {e}", file=sys.stderr)

        # Probe ref_kernel internals
        try:
            from reference import ref_kernel
            import types
            src = inspect.getsource(ref_kernel)
            # Print first 30 lines of ref_kernel source
            lines = src.split('\n')[:30]
            for i, line in enumerate(lines):
                print(f"[REF] L{i}: {line}", file=sys.stderr)
        except Exception as e:
            print(f"[REF] source error: {type(e).__name__}: {str(e)[:200]}", file=sys.stderr)

        # Also check: does generate_input pre-quantize A?
        try:
            from reference import generate_input
            src2 = inspect.getsource(generate_input)
            lines2 = src2.split('\n')[:40]
            for i, line in enumerate(lines2):
                print(f"[GEN] L{i}: {line}", file=sys.stderr)
        except Exception as e:
            print(f"[GEN] source error: {type(e).__name__}: {str(e)[:200]}", file=sys.stderr)

    # Normal ASM path
    kernel_name, log2_ks = _get_config(M, N, K)
    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)

    mn_key = (M, N)
    if mn_key not in _out_buf:
        _out_buf[mn_key] = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    out = _out_buf[mn_key]

    return aiter.gemm_a4w4_asm(
        A_q, B_shuffle, A_scale, B_scale_sh,
        out, kernel_name, bpreshuffle=True, log2_k_split=log2_ks,
    )

