"""
MXFP4 GEMM: Probe gemm_a4w4_blockscale_tune kernelId values + blockscale splitK.
Discover what CK tile configs are supported for our benchmark shapes.
"""

import sys
import torch
from task import input_t, output_t
from aiter import dtypes
import aiter
from aiter.ops.triton.quant import dynamic_mxfp4_quant
from aiter.utility.fp4_utils import e8m0_shuffle
from aiter.ops.gemm_op_a4w4 import get_GEMM_config

_out_buf: dict = {}
_ncalls = 0


def custom_kernel(data: input_t) -> output_t:
    global _ncalls
    _ncalls += 1

    A, B, B_q, B_shuffle, B_scale_sh = data
    M, K = A.shape
    N = B.shape[0]

    x_fp4, bs_e8m0 = dynamic_mxfp4_quant(A.contiguous())
    A_q = x_fp4.view(dtypes.fp4x2)
    A_scale = e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)

    mn_key = (M, N)
    if mn_key not in _out_buf:
        _out_buf[mn_key] = torch.empty(M, N, dtype=torch.bfloat16, device="cuda")
    out = _out_buf[mn_key]

    if _ncalls <= 2:
        print(f"\n[PROBE] Shape: M={M}, N={N}, K={K}", file=sys.stderr)

        # 1. Try blockscale with splitK values
        for sk in [0, 1, 2, 4, 8]:
            try:
                result = aiter.gemm_a4w4_blockscale(
                    A_q, B_shuffle, A_scale, B_scale_sh, out, sk,
                )
                print(f"[BS] splitK={sk} SUCCESS shape={result.shape}", file=sys.stderr)
            except Exception as e:
                err = str(e)[:200]
                print(f"[BS] splitK={sk}: {type(e).__name__}: {err}", file=sys.stderr)

        # 2. Try blockscale_tune with kernelId sweep (0-10)
        for kid in range(11):
            try:
                result = aiter.gemm_a4w4_blockscale_tune(
                    A_q, B_shuffle, A_scale, B_scale_sh, out, kid, 0,
                )
                print(f"[BST] kernelId={kid} SUCCESS shape={result.shape}", file=sys.stderr)
            except Exception as e:
                err = str(e)[:200]
                print(f"[BST] kernelId={kid}: {type(e).__name__}: {err}", file=sys.stderr)

        # 3. Check if blockscale has internal config selection
        try:
            import inspect
            src = inspect.getsource(aiter.gemm_a4w4_blockscale)
            for i, line in enumerate(src.split('\n')[:15]):
                print(f"[BS_SRC] L{i}: {line}", file=sys.stderr)
        except Exception as e:
            print(f"[BS_SRC] {type(e).__name__}: {str(e)[:200]}", file=sys.stderr)

        # 4. Look for CK tile blockscale config files
        try:
            import glob
            import os
            aiter_dir = os.path.dirname(aiter.__file__)
            configs = glob.glob(os.path.join(aiter_dir, "**/*blockscale*"), recursive=True)
            for c in configs[:10]:
                print(f"[CFG] {c}", file=sys.stderr)
            if not configs:
                # Try broader search for CK configs
                configs2 = glob.glob(os.path.join(aiter_dir, "configs/**/*.csv"), recursive=True)
                for c in configs2[:10]:
                    print(f"[CSV] {c}", file=sys.stderr)
        except Exception as e:
            print(f"[CFG] {type(e).__name__}: {str(e)[:200]}", file=sys.stderr)

        # 5. Check gemm_a4w4_blockscale module internals
        try:
            bs_mod = sys.modules.get("aiter.jit.module_gemm_a4w4_blockscale")
            if bs_mod:
                print(f"[MOD] blockscale module attrs: {dir(bs_mod)[:20]}", file=sys.stderr)
            else:
                print("[MOD] blockscale module not yet loaded", file=sys.stderr)
        except Exception as e:
            print(f"[MOD] {type(e).__name__}: {str(e)[:200]}", file=sys.stderr)

    # Fallback to ASM for actual computation
    kernel_name = None
    try:
        cfg = get_GEMM_config(M, N, K)
        if isinstance(cfg, dict):
            kn = cfg.get("kernelName")
            if kn is not None:
                kernel_name = str(kn)
    except Exception:
        pass
    if kernel_name is None:
        sym = f"f4gemm_bf16_per1x32Fp4_BpreShuffle_32x128"
        kernel_name = f"_ZN5aiter{len(sym)}{sym}E"

    return aiter.gemm_a4w4_asm(
        A_q, B_shuffle, A_scale, B_scale_sh,
        out, kernel_name, bpreshuffle=True,
    )

